using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Tools the agent can invoke
// ---------------------------------------------------------------------------

/// <summary>Simulated web-search tool that returns results for a query.</summary>
static class ResearchTools
{
    private static readonly List<string> s_notes = [];

    [Description("Search the web for information on a given query. Returns a list of relevant snippets.")]
    public static string WebSearch([Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍 Searching the web for: \"{query}\"");
        Console.ResetColor();

        // Simulated search results keyed on common research topics.
        var lowerQuery = query.ToLowerInvariant();

        if (lowerQuery.Contains("renewable energy"))
        {
            return """
            [1] "Solar and wind power accounted for 30 % of global electricity generation in 2025, up from 12 % in 2020." — IEA World Energy Outlook 2025
            [2] "Lithium-iron-phosphate batteries have cut grid-storage costs by 40 % since 2022, accelerating the retirement of coal plants." — BloombergNEF
            [3] "Offshore wind capacity is projected to triple by 2030, led by investments in the North Sea and the U.S. Atlantic coast." — GWEC Report
            """;
        }

        if (lowerQuery.Contains("artificial intelligence") || lowerQuery.Contains(" ai ") || lowerQuery.Contains("machine learning"))
        {
            return """
            [1] "Generative-AI adoption among enterprises reached 78 % in 2025, with code generation and customer-service bots as the top use cases." — McKinsey Tech Trends
            [2] "The EU AI Act entered full enforcement in August 2025, establishing risk-based regulation for AI systems." — European Commission
            [3] "Frontier model training costs dropped 5× between 2023 and 2025 thanks to advances in hardware and sparsity techniques." — Stanford HAI
            """;
        }

        if (lowerQuery.Contains("space exploration"))
        {
            return """
            [1] "NASA's Artemis III mission successfully landed astronauts on the lunar south pole in late 2025." — NASA Press Release
            [2] "SpaceX's Starship completed its first full orbital refueling demonstration in 2025." — SpaceNews
            [3] "The European Space Agency approved the Comet Interceptor mission for a 2029 launch." — ESA Bulletin
            """;
        }

        return $"""
        [1] "Overview article on '{query}' — a rapidly evolving field with significant recent breakthroughs." — Wikipedia
        [2] "Recent studies show increased global interest and funding in '{query}'." — Nature Reviews 2025
        [3] "Industry analysts project '{query}' market to grow 18 % CAGR through 2030." — Market Research Inc.
        """;
    }

    [Description("Save a research note for later reference. Use this to record key findings.")]
    public static string SaveNote([Description("The note text to save")] string note)
    {
        s_notes.Add(note);

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note saved (#{s_notes.Count})");
        Console.ResetColor();

        return $"Note #{s_notes.Count} saved successfully.";
    }

    [Description("Retrieve all previously saved research notes.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
            return "No notes have been saved yet.";

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📋 Retrieving {s_notes.Count} note(s)");
        Console.ResetColor();

        return string.Join("\n", s_notes.Select((n, i) => $"Note #{i + 1}: {n}"));
    }
}

// ---------------------------------------------------------------------------
// Build the agent
// ---------------------------------------------------------------------------

var topic = args.Length > 0 ? string.Join(' ', args) : "renewable energy trends in 2025";

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬 Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine($"Topic: {topic}");
Console.WriteLine();

// The chat client requires OPENAI_API_KEY (or OPENAI_BASE_URL for compatible
// providers) to be set.  When neither is available we fall back to a stub so
// the build & tool-wiring can still be demonstrated.
IChatClient chatClient;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

if (!string.IsNullOrWhiteSpace(apiKey))
{
    var baseUrl = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");
    OpenAI.OpenAIClientOptions? opts = null;
    if (!string.IsNullOrWhiteSpace(baseUrl))
    {
        opts = new OpenAI.OpenAIClientOptions { Endpoint = new Uri(baseUrl) };
    }

    var openAiClient = new OpenAI.OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey), opts);
    chatClient = openAiClient.GetChatClient(model).AsIChatClient();

    Console.WriteLine($"Using model: {model}");
}
else
{
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.WriteLine("⚠  OPENAI_API_KEY not set — running in demo mode (no real LLM calls).");
    Console.WriteLine("   Set OPENAI_API_KEY to enable live AI responses.");
    Console.ResetColor();
    chatClient = new DemoChatClient();
}

Console.WriteLine();

// Register tools
var tools = new AITool[]
{
    AIFunctionFactory.Create(ResearchTools.WebSearch),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

// Create the research agent
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI research assistant that searches the web and takes notes to produce a summary.",
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the WebSearch tool to find relevant information (make 2-3 searches with different queries).
        2. Use the SaveNote tool to record the most important findings from each search.
        3. Use the GetNotes tool to review all your notes.
        4. Produce a well-structured summary of your findings with key takeaways.
        Be thorough but concise.
        """,
    tools: tools);

// Run the agent
var session = await agent.CreateSessionAsync();

var userMessage = new ChatMessage(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}");

Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("▶ Agent is working...");
Console.ResetColor();
Console.WriteLine();

var response = await agent.RunAsync([ userMessage ], session);

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Cyan;
Console.WriteLine("═══════════════ Research Summary ═══════════════");
Console.ResetColor();
Console.WriteLine();

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && message.Text is { Length: > 0 } text)
    {
        Console.WriteLine(text);
    }
}

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Cyan;
Console.WriteLine("════════════════════════════════════════════════");
Console.ResetColor();

// ---------------------------------------------------------------------------
// Minimal demo chat-client used when no API key is configured.
// It simulates the agent loop: tool-call rounds then a final summary.
// ---------------------------------------------------------------------------
sealed class DemoChatClient : IChatClient
{
    private int _turn;

    public void Dispose() { }

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages, ChatOptions? options = null, CancellationToken ct = default)
        => throw new NotSupportedException();

    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages, ChatOptions? options = null, CancellationToken ct = default)
    {
        _turn++;

        // Determine available tools
        var availableTools = options?.Tools ?? [];

        if (_turn == 1 && availableTools.Count > 0)
        {
            // First turn: call WebSearch
            var msg = new ChatMessage(ChatRole.Assistant, [
                new FunctionCallContent("call_1", "WebSearch", new Dictionary<string, object?> { ["query"] = "renewable energy trends 2025" }),
            ]);
            return Task.FromResult(new ChatResponse(msg) { FinishReason = ChatFinishReason.ToolCalls });
        }

        if (_turn == 2 && availableTools.Count > 0)
        {
            // Second turn: call WebSearch again with a different query
            var msg = new ChatMessage(ChatRole.Assistant, [
                new FunctionCallContent("call_2", "WebSearch", new Dictionary<string, object?> { ["query"] = "renewable energy battery storage costs 2025" }),
            ]);
            return Task.FromResult(new ChatResponse(msg) { FinishReason = ChatFinishReason.ToolCalls });
        }

        if (_turn == 3 && availableTools.Count > 0)
        {
            // Third turn: save notes
            var msg = new ChatMessage(ChatRole.Assistant, [
                new FunctionCallContent("call_3", "SaveNote", new Dictionary<string, object?> { ["note"] = "Solar and wind reached 30% of global electricity in 2025. Battery costs dropped 40%." }),
                new FunctionCallContent("call_4", "SaveNote", new Dictionary<string, object?> { ["note"] = "Offshore wind capacity projected to triple by 2030." }),
            ]);
            return Task.FromResult(new ChatResponse(msg) { FinishReason = ChatFinishReason.ToolCalls });
        }

        if (_turn == 4 && availableTools.Count > 0)
        {
            // Fourth turn: retrieve notes
            var msg = new ChatMessage(ChatRole.Assistant, [
                new FunctionCallContent("call_5", "GetNotes"),
            ]);
            return Task.FromResult(new ChatResponse(msg) { FinishReason = ChatFinishReason.ToolCalls });
        }

        // Final turn: produce the summary
        var summary = """
            # Renewable Energy Trends in 2025

            ## Key Findings

            **1. Record-Breaking Adoption**
            Solar and wind power now account for 30% of global electricity generation,
            a dramatic increase from 12% in 2020.

            **2. Plummeting Storage Costs**
            Lithium-iron-phosphate (LFP) batteries have reduced grid-storage costs by 40%
            since 2022, making renewable energy more viable for baseload power.

            **3. Offshore Wind Expansion**
            Global offshore wind capacity is projected to triple by 2030, with major
            investments in the North Sea and the U.S. Atlantic coast.

            ## Takeaways
            - The energy transition is accelerating faster than most 2020-era forecasts predicted.
            - Battery storage cost reduction is the key enabler for retiring fossil-fuel plants.
            - Policy support and private investment continue to drive offshore wind growth.

            *Summary generated by ResearchAgent (demo mode)*
            """;

        var final = new ChatMessage(ChatRole.Assistant, summary);
        return Task.FromResult(new ChatResponse(final) { FinishReason = ChatFinishReason.Stop });
    }
}

